#include "ActualAuthoringRecording.h"
#include "ResearchAnnotations.h"
using namespace Research;
int main(int argc,char **argv){const auto report=argument(1);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(60,&app,[&]{QJsonArray checks;int failures=0;const auto folder=QFileInfo(report).absolutePath();auto check=[&](QString name,bool passed){checks.append(QJsonObject{{"name",name},{"passed",passed}});failures+=!passed;put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures}}).toJson());};
 check("inactive desktop",qEnvironmentVariable("TEXLINE_TEST_DESKTOP").startsWith("TeXlineValidation-"));
 QTemporaryDir secondVolume("D:/TeXworks-Research/validation/intuitive-cross-XXXXXX");check("private fixture on a second disk",secondVolume.isValid());if(!secondVolume.isValid()){app.exit(1);return;}
 const auto root=QFileInfo(folder+"/paper/main.tex").absoluteFilePath(),local=QFileInfo(folder+"/paper/local/supp.tex").absoluteFilePath(),external=secondVolume.filePath("supp.tex");const QByteArray other("External supplemental evidence.\n"),localBytes("Local supplemental evidence.\n");put(external,other);put(local,localBytes);
 const QString main="\\documentclass{article}\n\\begin{document}\nMain argument.\n\n\\end{document}\n";put(root,main.toUtf8());auto note=makeAnnotation(root,main,main.indexOf("Main argument"),"Main argument.",0,{});note.id="A01";note.opinion="Check the supplementary bound.";
 AnnotationRequest cached;cached.root=root;cached.sources={{root,main}};cached.notes={note};cached.engine=TWApp::instance()->getNamedEngine("pdfLaTeX");cached.auxiliaries={{QFileInfo(folder+"/paper/main.aux").absoluteFilePath(),"\\relax\n"},{secondVolume.filePath("main.aux"),"\\relax\n"}};
 auto annotations=compileAnnotations(cached,std::make_shared<std::atomic_bool>(false));put(folder+"/cache-compiler.txt",(annotations.error+"\n"+annotations.log).toUtf8());check("duplicate auxiliary cache on another disk cannot block annotations",annotations.error.isEmpty()&&!annotations.pdf.isEmpty());
 auto cross=cached;auto text=main;text.insert(text.indexOf("\\end{document}"),"\\input{local/supp}\n\\input{"+QDir::fromNativeSeparators(external)+"}\n");cross.sources={{root,text},{local,QString::fromUtf8(localBytes)},{QFileInfo(external).canonicalFilePath(),QString::fromUtf8(other)}};
 auto compiled=compileAnnotations(cross,std::make_shared<std::atomic_bool>(false));put(folder+"/dependencies-compiler.txt",(compiled.error+"\n"+compiled.log).toUtf8());check("actual cross-disk authored dependency compiles in isolation",compiled.error.isEmpty()&&!compiled.pdf.isEmpty());check("same-name dependencies on different disks remain distinct",contains(compiled.document,"External supplemental evidence")&&contains(compiled.document,"Local supplemental evidence"));check("copy map retains each original source identity",compiled.copyToOriginal.values().contains(QFileInfo(external).canonicalFilePath())&&compiled.copyToOriginal.values().contains(local));
 check("original files remain byte-identical",bytes(root)==main.toUtf8()&&bytes(local)==localBytes&&bytes(external)==other);auto cancel=std::make_shared<std::atomic_bool>(true);check("cross-disk compile cancellation publishes nothing",compileAnnotations(cross,cancel).cancelled);app.exit(failures?1:0);
});return app.exec();}
